    },
    {
      "kind": "delivery",
      "write": "the seller's delivery evidence: handover note, file list, delivery message"
    },
    {
      "kind": "communication",
      "write": "buyer-seller chat after delivery"
    }
  ],
  "hypotheses": [
    {
      "target_label": "met"
    },
    {
      "target_label": "missing"
    },
    {
      "target_label": "unverifiable"
    },
    {
      "target_label": "partial"
    }
  ]
